# Builds bot_page.js (page-side QA bot for running without node: load it in any browser tab that has the game open).
# Source of truth stays bot2.js: this only cuts out its in-page part and adds the outer loop (end detection, report) in-page.
import re, pathlib
d = pathlib.Path(__file__).parent
s = (d / 'bot2.js').read_text(encoding='utf-8')
a = s.index('await p.evaluate(async ([steps, GOD, NOMIX]) => {') + len('await p.evaluate(async ([steps, GOD, NOMIX]) => {')
b = s.index('}, [STEPS, GOD, +(process.env.NOMIX || 0)]);')
body = s[a:b].replace("import('/js/engine.js?v=' + v)", "import(new URL('./js/engine.js?v=' + v, location.href).href)")
out = '''// GENERATED by mkpage.py from bot2.js — do not edit. Usage in the page: await __qaBot({steps:30, god:false, nomix:3}); then poll __qaStatus().
window.__qaBot = async function (qo) { qo = qo || {}; if (window.__qaOn) return 'already'; window.__qaOn = 1; const steps = qo.steps || 30, GOD = !!qo.god, NOMIX = qo.nomix || 0; window.__NOBOW = !!qo.nobow;
''' + body + '''
  window.__qaEnd = null; setInterval(() => { try { const e = document.getElementById('end'); if (!window.__qaEnd && e.classList.contains('on')) window.__qaEnd = { gt: +(__G.time - __ST.t0).toFixed(0), eh: document.getElementById('eh').textContent, st: document.getElementById('stl').innerText.split(String.fromCharCode(10)).join(' / ') }; } catch (e) { } }, 300);
  return 'started'; };
window.__qaStatus = function (full) { const G = __G, S = window.__ST || {}, P = G.player, B = G.boss; const r = { m: G.mis && G.mis.id, gt: +(G.time - (S.t0 || 0)).toFixed(0), end: window.__qaEnd, P: P ? [P.x | 0, P.z | 0] : null, hp: P ? (P.hp | 0) + '/' + (P.maxHp | 0) : '', en: G.ents.filter(e => e.team === 'enemy' && !e.dead && !e.prop).length, boss: B && !B.dead ? B.type + ':' + (B.hp | 0) + '/' + (B.maxHp | 0) : '', obj: document.getElementById('obj').textContent.slice(0, 60), ST: S, msPerStep: S.n ? +(S.ms / S.n).toFixed(1) : null, hidden: document.hidden, err: window.__be || 0 }; if (full) { r.TL = window.__TL.slice(); window.__TL.length = 0; } return JSON.stringify(r); };
window.__qaSum = function () { const G = __G, S = window.__ST || {}, P = G.player, B = G.boss, bs = S.bst || {}, n = Object.values(bs).reduce((a, b) => a + b, 0); return JSON.stringify({ m: G.mis && G.mis.id, gt: +(G.time - (S.t0 || 0)).toFixed(0), won: !!window.__qaEnd, stars: window.__qaEnd ? (window.__qaEnd.st.match(/★/g) || []).length : 0, fight: S.b0 ? +((S.duelS || 0) * .15).toFixed(0) : null, bMax: S.b0 ? S.b0.max : null, bossLeft: B && !B.dead ? +(B.hp / B.maxHp).toFixed(2) : S.bossMinHp, deaths: S.deaths, hits: S.hits, pMin: S.pMinHp, stag: n ? +((bs.stagger || 0) / n).toFixed(2) : null, obj: document.getElementById('obj').textContent.slice(0, 50) }); };
'''
(d / 'bot_page.js').write_bytes(out.encode('utf-8'))
print('ok', len(out))
